using Microsoft.Data.Sqlite;using System.Collections.ObjectModel;using System.Windows;using System.Windows.Controls;using System.IO;
namespace AyGest.Wpf;
public partial class SalesPosWindow:Window{
 readonly string _db=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"AyGest","aygest.db");readonly ObservableCollection<CartRow> _cart=new();readonly List<Product> _products=new();decimal _discount;string _payment="Dinheiro";
 public SalesPosWindow(){InitializeComponent();Directory.CreateDirectory(Path.GetDirectoryName(_db)!);EnsureSchema();CartGrid.ItemsSource=_cart;Load();}
 SqliteConnection C()=>new($"Data Source={_db}");
 void EnsureSchema(){using var c=C();c.Open();using var q=c.CreateCommand();q.CommandText="CREATE TABLE IF NOT EXISTS sales(id INTEGER PRIMARY KEY AUTOINCREMENT,number TEXT NOT NULL UNIQUE,customer_id INTEGER,customer_name TEXT,subtotal REAL NOT NULL,discount REAL NOT NULL,vat REAL NOT NULL,total REAL NOT NULL,payment_method TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'Concluída',created_at TEXT NOT NULL);CREATE TABLE IF NOT EXISTS sale_items(id INTEGER PRIMARY KEY AUTOINCREMENT,sale_id INTEGER NOT NULL,product_id INTEGER NOT NULL,sku TEXT,product_name TEXT NOT NULL,quantity REAL NOT NULL,unit_price REAL NOT NULL,discount REAL NOT NULL DEFAULT 0,vat REAL NOT NULL DEFAULT 0,total REAL NOT NULL);CREATE TABLE IF NOT EXISTS suspended_sales(id INTEGER PRIMARY KEY AUTOINCREMENT,number TEXT NOT NULL UNIQUE,customer_name TEXT,payload TEXT NOT NULL,created_at TEXT NOT NULL);";q.ExecuteNonQuery();}
 void Load(){_products.Clear();using var c=C();c.Open();using var q=c.CreateCommand();q.CommandText="SELECT id,sku,name,COALESCE(category,''),sale_price,stock,vat FROM products WHERE status='Activo' ORDER BY name";using var r=q.ExecuteReader();while(r.Read())_products.Add(new(r.GetInt64(0),r.GetString(1),r.GetString(2),r.GetString(3),r.GetDecimal(4),r.GetDecimal(5),r.GetDecimal(6)));CategoryBox.Items.Clear();CategoryBox.Items.Add(new ComboBoxItem{Content="Todas categorias"});foreach(var x in _products.Select(x=>x.Category).Where(x=>x!="").Distinct().OrderBy(x=>x))CategoryBox.Items.Add(new ComboBoxItem{Content=x});CategoryBox.SelectedIndex=0;RenderProducts();LoadCustomers();RefreshTotals();CheckCash();}
 void LoadCustomers(){CustomerBox.Items.Clear();CustomerBox.Items.Add("Consumidor final");using var c=C();c.Open();using var q=c.CreateCommand();q.CommandText="SELECT name FROM clientes ORDER BY name";try{using var r=q.ExecuteReader();while(r.Read())CustomerBox.Items.Add(r.GetString(0));}catch{}CustomerBox.SelectedIndex=0;}
 void RenderProducts(){ProductsPanel.Children.Clear();var text=(SearchBox.Text??"").Trim().ToLowerInvariant();var cat=(CategoryBox.SelectedItem as ComboBoxItem)?.Content?.ToString();foreach(var p in _products.Where(p=>(text==""||$"{p.Sku} {p.Name}".ToLowerInvariant().Contains(text))&&(cat=="Todas categorias"||string.IsNullOrEmpty(cat)||p.Category==cat))){var b=new Button{Width=190,Height=115,Margin=new Thickness(6),Tag=p,Content=new StackPanel{Children={new TextBlock{Text=p.Name,FontWeight=FontWeights.SemiBold,TextWrapping=TextWrapping.Wrap,FontSize=15},new TextBlock{Text=p.Sku,Foreground=System.Windows.Media.Brushes.Gray},new TextBlock{Text=$"{p.SalePrice:N2} MT",FontSize=18,FontWeight=FontWeights.Bold},new TextBlock{Text=$"Stock: {p.Stock:N2}",FontSize=11}}}};b.Click+=Product_Click;ProductsPanel.Children.Add(b);}}
 void Product_Click(object s,RoutedEventArgs e){if((s as Button)?.Tag is Product p)Add(p,1);}
 void Add(Product p,decimal qty){var current=_cart.FirstOrDefault(x=>x.ProductId==p.Id);var newQty=(current?.Quantity??0)+qty;if(newQty>p.Stock){MessageBox.Show($"Stock insuficiente para {p.Name}.\nDisponível: {p.Stock:N2}","Stock",MessageBoxButton.OK,MessageBoxImage.Warning);return;}if(current!=null)_cart[_cart.IndexOf(current)]=current with{Quantity=newQty,Total=newQty*p.SalePrice};else _cart.Add(new(p.Id,p.Sku,p.Name,qty,p.SalePrice,qty*p.SalePrice,p.Vat));RefreshTotals();}
 void SearchChanged(object s,EventArgs e)=>RenderProducts();void Clear_Click(object s,RoutedEventArgs e){_cart.Clear();_discount=0;RefreshTotals();}
 void RefreshTotals(){var sub=_cart.Sum(x=>x.Total);var vat=_cart.Sum(x=>x.Total*x.Vat/100m);var total=Math.Max(0,sub-_discount+vat);SubtotalText.Text=$"Subtotal: {sub:N2} MT";DiscountText.Text=$"Desconto: {_discount:N2} MT";VatText.Text=$"IVA: {vat:N2} MT";TotalText.Text=$"Total: {total:N2} MT";ItemsText.Content=_cart.Sum(x=>x.Quantity).ToString("N2");using var c=C();c.Open();using var q=c.CreateCommand();q.CommandText="SELECT COUNT(*),COALESCE(SUM(total),0) FROM sales WHERE date(created_at)=date('now','localtime') AND status='Concluída'";using var r=q.ExecuteReader();if(r.Read()){SalesTodayText.Content=r.GetInt32(0);SalesTotalText.Content=$"{r.GetDecimal(1):N2} MT";}}
 void CheckCash(){using var c=C();c.Open();using var q=c.CreateCommand();q.CommandText="SELECT COUNT(*) FROM cash_sessions WHERE status='Aberto'";var open=Convert.ToInt32(q.ExecuteScalar())>0;CashStatusText.Text=open?"● Caixa aberto":"○ Caixa fechado";}
 void Cash_Click(object s,RoutedEventArgs e){_payment="Dinheiro";Checkout_Click(s,e);}void Mpesa_Click(object s,RoutedEventArgs e){_payment="M-Pesa";Checkout_Click(s,e);}void Card_Click(object s,RoutedEventArgs e){_payment="Cartão";Checkout_Click(s,e);}
 void Checkout_Click(object s,RoutedEventArgs e){if(!_cart.Any()){MessageBox.Show("Adicione produtos ao carrinho.");return;}using var c=C();c.Open();using var cash=c.CreateCommand();cash.CommandText="SELECT id FROM cash_sessions WHERE status='Aberto' ORDER BY id DESC LIMIT 1";var sid=cash.ExecuteScalar();if(sid==null){MessageBox.Show("Abra o caixa antes de finalizar a venda.","Caixa",MessageBoxButton.OK,MessageBoxImage.Warning);return;}var total=_cart.Sum(x=>x.Total)-_discount+_cart.Sum(x=>x.Total*x.Vat/100m);using var tx=c.BeginTransaction();var num="FT"+DateTime.Now.ToString("yyyyMMddHHmmssfff");using var q=c.CreateCommand();q.Transaction=tx;q.CommandText="INSERT INTO sales(number,customer_name,subtotal,discount,vat,total,payment_method,created_at) VALUES($n,$customer,$sub,$disc,$vat,$total,$method,$d);SELECT last_insert_rowid();";q.Parameters.AddWithValue("$n",num);q.Parameters.AddWithValue("$customer",CustomerBox.SelectedItem?.ToString()??"Consumidor final");q.Parameters.AddWithValue("$sub",_cart.Sum(x=>x.Total));q.Parameters.AddWithValue("$disc",_discount);q.Parameters.AddWithValue("$vat",_cart.Sum(x=>x.Total*x.Vat/100m));q.Parameters.AddWithValue("$total",total);q.Parameters.AddWithValue("$method",_payment);q.Parameters.AddWithValue("$d",DateTime.UtcNow.ToString("O"));var saleId=Convert.ToInt64(q.ExecuteScalar());foreach(var x in _cart){using var i=c.CreateCommand();i.Transaction=tx;i.CommandText="INSERT INTO sale_items(sale_id,product_id,sku,product_name,quantity,unit_price,vat,total) VALUES($sid,$pid,$sku,$name,$qty,$price,$vat,$total)";i.Parameters.AddWithValue("$sid",saleId);i.Parameters.AddWithValue("$pid",x.ProductId);i.Parameters.AddWithValue("$sku",x.Sku);i.Parameters.AddWithValue("$name",x.Product);i.Parameters.AddWithValue("$qty",x.Quantity);i.Parameters.AddWithValue("$price",x.UnitPrice);i.Parameters.AddWithValue("$vat",x.Vat);i.Parameters.AddWithValue("$total",x.Total);i.ExecuteNonQuery();using var u=c.CreateCommand();u.Transaction=tx;u.CommandText="UPDATE products SET stock=stock-$qty,updated_at=$d WHERE id=$id AND stock >= $qty";u.Parameters.AddWithValue("$qty",x.Quantity);u.Parameters.AddWithValue("$id",x.ProductId);u.Parameters.AddWithValue("$d",DateTime.UtcNow.ToString("O"));if(u.ExecuteNonQuery()!=1){tx.Rollback();MessageBox.Show("A venda não pôde ser concluída porque o stock mudou.");return;}using var m=c.CreateCommand();m.Transaction=tx;m.CommandText="INSERT INTO stock_movements(product_id,type,quantity,unit_cost,reference,notes,created_at) VALUES($id,'Venda',$qty,$cost,$ref,'Baixa automática do POS',$d)";m.Parameters.AddWithValue("$id",x.ProductId);m.Parameters.AddWithValue("$qty",-x.Quantity);m.Parameters.AddWithValue("$cost",0);m.Parameters.AddWithValue("$ref",num);m.Parameters.AddWithValue("$d",DateTime.UtcNow.ToString("O"));m.ExecuteNonQuery();}using var cm=c.CreateCommand();cm.Transaction=tx;cm.CommandText="INSERT INTO cash_movements(session_id,type,description,reference,method,amount,created_at) VALUES($sid,'Recebimento','Venda POS',$ref,$method,$amount,$d)";cm.Parameters.AddWithValue("$sid",sid);cm.Parameters.AddWithValue("$ref",num);cm.Parameters.AddWithValue("$method",_payment);cm.Parameters.AddWithValue("$amount",total);cm.Parameters.AddWithValue("$d",DateTime.UtcNow.ToString("O"));cm.ExecuteNonQuery();tx.Commit();MessageBox.Show($"Venda {num} concluída.\nTotal: {total:N2} MT\nPagamento: {_payment}","Venda concluída",MessageBoxButton.OK,MessageBoxImage.Information);_cart.Clear();RefreshTotals();Load();}
 void NewSale_Click(object s,RoutedEventArgs e)=>Clear_Click(s,e);void Barcode_Click(object s,RoutedEventArgs e){var code=Microsoft.VisualBasic.Interaction.InputBox("Código de barras ou SKU:","Produto","").Trim();var p=_products.FirstOrDefault(x=>x.Sku.Equals(code,StringComparison.OrdinalIgnoreCase));if(p==null){MessageBox.Show("Produto não encontrado.");return;}Add(p,1);}
 void Suspend_Click(object s,RoutedEventArgs e){if(!_cart.Any())return;MessageBox.Show("Venda suspensa. A persistência de suspensas será ligada ao histórico de POS na próxima camada.");}
 void Suspended_Click(object s,RoutedEventArgs e)=>MessageBox.Show("Nenhuma venda suspensa disponível.");
 void History_Click(object s,RoutedEventArgs e){using var c=C();c.Open();using var q=c.CreateCommand();q.CommandText="SELECT number,customer_name,total,payment_method,created_at,status FROM sales ORDER BY id DESC LIMIT 30";using var r=q.ExecuteReader();var sb=new System.Text.StringBuilder("Últimas vendas\n\n");while(r.Read())sb.AppendLine($"{r.GetString(0)} | {r.GetString(1)} | {r.GetDecimal(2):N2} MT | {r.GetString(3)} | {r.GetString(4)}");MessageBox.Show(sb.ToString(),"Histórico",MessageBoxButton.OK,MessageBoxImage.Information);}
 public record Product(long Id,string Sku,string Name,string Category,decimal SalePrice,decimal Stock,decimal Vat);public record CartRow(long ProductId,string Sku,string Product,decimal Quantity,decimal UnitPrice,decimal Total,decimal Vat);
}
